tools.args:
{"command":"$ErrorActionPreference = 'Stop'
$token = $env:SCREENPIPE_LOCAL_API_KEY
if (-not $token) {
    $token = "$(cd "$(mktemp -d)" && bun x screenpipe@latest auth token)"
    $env:SCREENPIPE_LOCAL_API_KEY = $token
}
$base = $env:SCREENPIPE_LOCAL_API_URL ?? 'http://localhost:3030'
$headers = @{
    'Authorization' = "Bearer $token"
    'X-Screenpipe-Client' = 'api'
    'X-Screenpipe-Agent' = 'claude'
}
$url = "$base/activity-summary?start_time=2026-10-18T00:00:00%2B03:00&end_time=2026-10-18T23:59:59%2B03:00&include_key_texts=false&include_apps=true&include_windows=true"
$resp = Invoke-WebRequest -Uri $url -Headers $headers -ContentType 'application/json'
$body = $resp.Content | ConvertFrom-Json
$body | ConvertTo-Json -Depth 10","description":"Fetch yesterday's screenpipe activity summary"}

{"path":"C:\Users\spay\AppData\Local\Temp\sp_token.ps1","content":"$ErrorActionPreference = 'Stop'
$env:SCREENPIPE_LOCAL_API_KEY = & bun x screenpipe@latest auth token 2>$null | Out-String | ForEach-Object { $_.Trim() }
$headers = @{
    'Authorization' = "Bearer $($env:SCREENPIPE_LOCAL_API_KEY)"
    'X-Screenpipe-Client' = 'api'
    'X-Screenpipe-Agent' = 'claude'
}
$base = 'http://localhost:3030'
$url = "$base/activity-summary?start_time=2026-10-18T00:00:00%2B03:00&end_time=2026-10-18T23:59:59%2B03:00&include_key_texts=false"
$resp = Invoke-WebRequest -Uri $url -Headers $headers -ContentType 'application/json'
[System.IO.File]::WriteAllText("$env:TEMP\sp_summary.json", $resp.Content)
"}
